<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Domain;

/**
 * Raw template content, resolved variables, and rendering options passed to the rendering engine.
 *
 * The use case is responsible for resolving these values (template lookup, version selection,
 * variable merging, snippet loading, asset collection) before handing this object to the gateway.
 */
class TemplateRenderRequest
{
    /**
     * @param array<string, string> $snippets  Snippet HTML indexed by code (e.g. "HEADER", "FOOTER").
     *                                          Exposed as Handlebars partials: {{>HEADER}}.
     * @param array<string, string> $variables  Merged variable map in flat dotted-key format (e.g. "user.name").
     *                                          Tenant-level defaults have already been merged; call-site values take precedence.
     * @param RenderedAsset[]       $assets     Assets to include with the rendered document (e.g. theme CSS).
     */
    public function __construct(
        private readonly string $htmlContent,
        private readonly array $snippets = [],
        private readonly array $variables = [],
        private readonly TemplateOutputFormat $outputFormat = TemplateOutputFormat::HTML,
        private readonly ?string $subject = null,
        private readonly ?string $textContent = null,
        private readonly array $assets = [],
    ) {
    }

    /** Raw HTML content with Handlebars placeholders. Never null. */
    public function htmlContent(): string
    {
        return $this->htmlContent;
    }

    /** @return array<string, string> */
    public function snippets(): array
    {
        return $this->snippets;
    }

    /** @return array<string, string> */
    public function variables(): array
    {
        return $this->variables;
    }

    /** Desired output format. Controls post-processing such as CSS inlining for HTML_EMBEDDED. */
    public function outputFormat(): TemplateOutputFormat
    {
        return $this->outputFormat;
    }

    /** Raw subject string. Null for channels that do not use a subject (e.g. SMS). */
    public function getSubject(): ?string
    {
        return $this->subject;
    }

    /** Raw plain-text content. Null when the template version does not define a text alternative. */
    public function getTextContent(): ?string
    {
        return $this->textContent;
    }

    /** @return RenderedAsset[] */
    public function assets(): array
    {
        return $this->assets;
    }
}
